<template>
  <base-layout>
    <v-toolbar
      flat
      color="grey lighten-3"
      height="50"
    >
      <v-toolbar-title>Profile</v-toolbar-title>
    </v-toolbar>
    <v-layout
      row
      wrap
      class="grey lighten-5"
    >
      <v-flex
        md4
        xs12
      >
        <v-card class="mx-2 mt-2 px-2 pt-2">
          <v-text-field
            label="Username"
            v-model="userInfo.username"
            :disabled="true"
          ></v-text-field>
          <v-text-field
            label="Role Name"
            v-model="userInfo.roleName"
            :disabled="true"
          ></v-text-field>
        </v-card>
      </v-flex>
      <v-flex
        md8
        xs12
      >
        <div class="my-2 px-2">
          <v-alert
            type="success"
            :value="message.success"
          >
            {{message.success}}
          </v-alert>
          <v-alert
            type="error"
            :value="message.error"
          >
            {{message.error}}
          </v-alert>
        </div>
        <v-card class="mx-2 my-2">
          <v-toolbar
            color="grey lighten-5"
            flat
            dense
          >
            <v-toolbar-title>Change Password</v-toolbar-title>
          </v-toolbar>
          <v-divider></v-divider>
          <v-form
            ref="form"
            class="pa-2"
          >
            <div class="mx-2">
              <v-text-field
                label="Old Password"
                name="Old Password"
                v-model="input.passwordOld"
                :error-messages="errors.collect('Old Password')"
                type="password"
                v-validate="'required'"
              ></v-text-field>
              <v-text-field
                label="New Password"
                name="New Password"
                v-model="input.passwordNew"
                :error-messages="errors.collect('New Password')"
                type="password"
                v-validate="'required'"
              ></v-text-field>
              <v-text-field
                label="Confirm New Password"
                name="Confirm New Password"
                v-model="input.passwordNewConfirm"
                :error-messages="errors.collect('Confirm New Password')"
                type="password"
                v-validate="{required: true, confirmed:input.passwordNew}"
              ></v-text-field>
            </div>
            <div class="mt-3">
              <v-btn
                color="primary"
                @click="submit()"
              >Save New Password</v-btn>
            </div>
          </v-form>
        </v-card>
      </v-flex>
    </v-layout>
  </base-layout>
</template>

<script>
import { post } from "@/utils/proxy";

export default {
  data() {
    return {
      error: null,
      input: {
        passwordOld: "",
        passwordNew: "",
        passwordNewConfirm: ""
      },
      message: {
        success: "",
        error: ""
      }
      // userInfo: {
      //   name: 'Admin',
      //   role: 'Administrator',
      // },
    };
  },
  computed: {
    userInfo() {
      return this.$store.state.auth.user;
    }
  },
  methods: {
    submit() {
      this.message = {
        success: "",
        error: ""
      };
      this.$validator.validateAll().then(() => {
        if (!this.errors.any()) {
          post("app/changePassword", {
            passwordOld: this.input.passwordOld,
            passwordNew: this.input.passwordNew
          }).then(response => {
            if (response.success_message) {
              this.input = {
                passwordOld: "",
                passwordNew: "",
                passwordNewConfirm: ""
              };
              this.$validator.reset();
              this.errors.clear();
              this.message.success = "Password successfully changed";
            } else {
              this.message.error = "The password that you entered is not valid";
            }
          });
        } else {
          $(`[name="${this.errors.items[0].field}"]`).focus();
        }
      });
    }
  }
};
</script>



